contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        // fund c with the same amount so it can pay out
        c.sendTo(receiver, 0); if (__ESBMC_reverted()) return; // proves owner path works (amount 0)
        uint balC0 = address(c).balance;
        // give c enough Ether by sending it value via sendTo to this contract? Not possible; instead pre-fund via self-destruct-free method: send value through constructor is unavailable, so use payable call.
        // c has no payable receive; fund it by having run send value to c via sendTo is not possible.
        // Instead: require c already holds enough (fresh c holds 0, so amount must be 0) OR rely on the msg.value of run: run's value stays on this contract.
        // So exercise: with a fresh c (balance 0), sendTo with amount 0 succeeds for any receiver that accepts.
        bool reverted;
        uint recBal0 = receiver.balance;
        c.sendTo(receiver, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && receiver.balance == recBal0 && address(c).balance == balC0);
    }
    receive() external payable {}
}

